INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18313$nota-0231$m18313$, $m18314$Exercise Physiology McArdle.pdf$m18314$, $m18315$206$m18315$, $m18316$Cyclists who spend the most time training at or above their lactate threshold (LT) increase gross efficiency cycling compared to preseason and postseason. The increase in gross efficiency averages a modest 1%, yet this can make a difference in winning or losing, and posting a rider's best times.$m18316$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18317$nota-0231$m18317$, $m18318$Exercise Physiology McArdle.pdf$m18318$, $m18319$206$m18319$, $m18320$Source: Hopker J, et al. Changes in cycling efficiency during a competitive season. Med Sci Sport Exer 2009;41:912.$m18320$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18321$nota-0231$m18321$, $m18322$nota-0215$m18322$, $m18323$complementa$m18323$, $m18324$nota-0215 já registra que a eficiência de pedalada melhora ~8% ao longo de VÁRIOS ANOS de treino; este estudo (Hopker 2009) mostra uma mudança menor (~1%) e de prazo mais curto (dentro de UMA temporada), especificamente associada ao volume de treino em/acima do limiar de lactato$m18324$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18325$nota-0239$m18325$, $m18326$Exercise Physiology McArdle.pdf$m18326$, $m18327$346$m18327$, $m18328$Cardiovascular Drift: Reduced Stroke Volume and Increased Heart Rate During Prolonged Physical Activity... A reduced stroke volume initiates a compensatory progressive heart rate increase to maintain a nearly constant cardiac output as activity progresses and body temperature increases. The term cardiovascular drift describes the gradual time-dependent downward 'drift' in several cardiovascular responses, most notably stroke volume with concomitant heart rate increase during prolonged steady-rate exercise, particularly during high ambient temperatures.$m18328$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18329$nota-0239$m18329$, $m18330$Exercise Physiology McArdle.pdf$m18330$, $m18331$347$m18331$, $m18332$From 15 to 55 min during the control trial, a 13% decrease in stroke volume accompanied an 11% heart rate increase, while cutaneous blood flow showed no increase from 20 to 60 min of cycling... These observations confirm that a decline in stroke volume during prolonged physical activity in a thermoneutral environment primarily results from increased heart rate and not increased cutaneous blood flow as body temperature rises.$m18332$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18333$nota-0239$m18333$, $m18334$nota-0182$m18334$, $m18335$complementa$m18335$, $m18336$nota-0182 (Fonte 2) descreve o mecanismo de deriva cardíaca apenas qualitativamente; esta nota traz o dado mais quantificado do cânone (4 fontes) sobre o fenômeno, incluindo um experimento com bloqueio beta-1 que aponta a direção causal entre FC e volume sistólico.$m18336$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18337$nota-0240$m18337$, $m18338$Exercise Physiology McArdle.pdf$m18338$, $m18339$378$m18339$, $m18340$Table 18.2 Classification of Human Skeletal Muscle Fiber Types... Type I Fibers: Contraction time Slow; Maximum duration of use Hours; Force production Low; Mitochondrial density High. Type IIa Fibers: Moderately fast; <30 min; Medium; High. Type IIx Fibers: Fast; <5 min; High; Medium. Type IIb Fibers: Very fast; <1 min; Very high; Low.$m18340$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18341$nota-0240$m18341$, $m18342$Exercise Physiology McArdle.pdf$m18342$, $m18343$379$m18343$, $m18344$Athletic groups with the highest aerobic and endurance capacities (e.g., distance runners and cross-country skiers) possess the highest percentage of slow-twitch fibers, often 90 to 95% in the leg's gastrocnemius muscle. Weightlifters, ice hockey players, and sprinters have more fast-twitch fibers and relatively lower aerobic capacities... Men, women, and children on average possess 45 to 55% slow-twitch fibers in their arm and leg muscles.$m18344$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18345$nota-0240$m18345$, $m18346$nota-0074$m18346$, $m18347$complementa$m18347$, $m18348$nota-0074 (Livro 1) estabelece que a FTP marca o início do recrutamento significativo de fibras rápidas; esta nota detalha as características metabólicas de cada subtipo de fibra (incluindo tempo máximo de uso sustentável) e a distribuição real observada em atletas de elite de endurance vs. potência.$m18348$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18349$nota-0240$m18349$, $m18350$nota-0068$m18350$, $m18351$complementa$m18351$, $m18352$reforça, com dados populacionais, por que força/fibras rápidas raramente são o fator limitante no ciclismo de endurance$m18352$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18353$nota-0241$m18353$, $m18354$Exercise Physiology McArdle.pdf$m18354$, $m18355$422$m18355$, $m18356$Figure 20.10 illustrates the catecholamine response at various cycling intensities (expressed as %VO2max) in 10 male subjects. Norepinephrine increases markedly at intensities that exceed 50% VO2max, whereas epinephrine levels remain unchanged until cycling intensity exceeds the 75% level. At maximum effort, an approximate two- to sixfold increase in norepinephrine release takes place.$m18356$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18357$nota-0241$m18357$, $m18358$Exercise Physiology McArdle.pdf$m18358$, $m18359$422$m18359$, $m18360$The sympathoadrenal response to physical activity most closely relates to relative rather than absolute activity intensity.$m18360$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18361$nota-0241$m18361$, $m18362$nota-0145$m18362$, $m18363$complementa$m18363$, $m18364$oferece um mecanismo hormonal quantificado que ajuda a explicar por que a intensidade em torno de 75% do VO2máx (próxima da faixa de limiar/FTP) marca uma transição fisiológica qualitativa, distinta do limiar de lactato em si$m18364$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18365$nota-0254$m18365$, $m18366$Exercise Physiology McArdle.pdf$m18366$, $m18367$633$m18367$, $m18368$The major portion of acclimatization occurs during the first week of heat exposure, with full acclimatization thereafter. The process requires only 2 to 4 hr of daily heat exposure. The first several sessions in the heat should include 15 to 20 min of light-intensity physical activity. Exercise sessions then should increase in duration and intensity.$m18368$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18369$nota-0254$m18369$, $m18370$Exercise Physiology McArdle.pdf$m18370$, $m18371$633$m18371$, $m18372$Sweating capacity, the most significant factor for heat acclimatization, increases early and nearly doubles after 10 days of heat exposure; sweat also becomes more dilute (less salt lost) and distributes more evenly over the skin surface... The major benefits of acclimatization dissipate within 2 to 3 wk after returning to a more temperate environment.$m18372$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18373$nota-0254$m18373$, $m18374$nota-0227$m18374$, $m18375$complementa$m18375$, $m18376$nota-0227 cobre o protocolo de reposição de fluido durante o exercício; esta nota cobre a adaptação fisiológica que reduz a necessidade de reposição ao longo dos dias de exposição ao calor$m18376$)
